<?php session_start();require_once __DIR__.'/../../src/db.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!isset($_FILES['image'])||$_FILES['image']['error'])throw new RuntimeException('Выберите изображение');$f=$_FILES['image'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Допустимы JPG, PNG, WebP');if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0775,true);$name=bin2hex(random_bytes(10)).'.'.$ext;move_uploaded_file($f['tmp_name'],UPLOAD_DIR.'/'.$name);$title=trim($_POST['title']);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['slug']?:bin2hex(random_bytes(4))));$q=db()->prepare("INSERT INTO panoramas(title,slug,description,image,published) VALUES(?,?,?,?,?)");$q->execute([$title,$slug,trim($_POST['description']),'/uploads/'.$name,isset($_POST['published'])?1:0]);header('Location:/admin/');exit;}catch(Throwable $e){$err=$e->getMessage();}}?>
